/**
 * The meaning layer of a passage, as a table a person can read and check:
 *   node local/quran-meaning.mjs --passage "95, 93:1-11" [--out <dir>]
 * For each ayah: the verified Arabic (Tanzil Uthmani), Pickthall's
 * translation (1930, public domain), the visible things the Arabic names,
 * the themes the translation gives, what is unseen, and the gaps. Saved:
 * meaning.md and meaning.json. Nothing here is generated by a model.
 */
import { mkdir, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { meaningTable, passageMeaning } from "../engine/src/quran-meaning.mjs";
import { parsePassage } from "../engine/src/quran-locate.mjs";
import { loadQuran, loadQuranTexts, parseArgs } from "./voice-film.mjs";

async function main() {
  const args = /** @type {Record<string, any>} */ (parseArgs(process.argv.slice(2)));
  const { surahNames } = await loadQuran();
  const parsed = parsePassage({ passage: args.passage, surah: args.surah, ayat: args.ayat }, surahNames);
  if (!parsed.ok) { console.error(parsed.message.code); process.exit(2); }
  const p = passageMeaning(await loadQuranTexts(), parsed.ranges);
  const md = `${meaningTable(p)}\n\n${p.summary.ayat} ayat: ${p.summary.withThings} name a visible thing, ${p.summary.withThemes} have a theme, ${p.summary.unseen} touch the unseen, ${p.summary.gaps} have a gap.\n${p.tafsir}\n`;
  if (typeof args.out === "string") {
    const out = resolve(args.out);
    await mkdir(out, { recursive: true });
    await writeFile(join(out, "meaning.md"), md);
    await writeFile(join(out, "meaning.json"), JSON.stringify(p, null, 1));
  }
  console.log(md);
}

if (import.meta.url === `file://${process.argv[1]}`) main().catch((e) => { console.error(e.message); process.exit(1); });
